-- TrendPulse migration 001: initial medallion schema (generated by scripts/export_sql_migrations.py)
-- Applied automatically by the pipeline; safe to run by hand in the Supabase SQL editor.
CREATE SCHEMA IF NOT EXISTS trendpulse;
SET search_path TO trendpulse;
-- Keep the warehouse out of Supabase's auto-generated REST API.
REVOKE ALL ON SCHEMA trendpulse FROM anon, authenticated;

CREATE TABLE IF NOT EXISTS api_request_log (
	id SERIAL NOT NULL, 
	run_id VARCHAR(36), 
	endpoint VARCHAR(48) NOT NULL, 
	region_code VARCHAR(8), 
	discovery_method VARCHAR(24), 
	params_json TEXT, 
	http_status INTEGER, 
	quota_cost INTEGER NOT NULL, 
	items_returned INTEGER, 
	duration_ms INTEGER, 
	attempt INTEGER, 
	requested_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	error TEXT, 
	PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS ix_api_log_requested ON api_request_log (requested_at);
CREATE INDEX IF NOT EXISTS ix_api_log_run ON api_request_log (run_id);

CREATE TABLE IF NOT EXISTS bridge_video_topics (
	video_id VARCHAR(32) NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	confidence FLOAT NOT NULL, 
	assignment_method VARCHAR(24) NOT NULL, 
	review_status VARCHAR(16) NOT NULL, 
	matched_terms TEXT, 
	assigned_run_id VARCHAR(36) NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_bridge_video_topics PRIMARY KEY (video_id, topic_id)
);
CREATE INDEX IF NOT EXISTS ix_bridge_review ON bridge_video_topics (review_status);
CREATE INDEX IF NOT EXISTS ix_bridge_topic ON bridge_video_topics (topic_id);

CREATE TABLE IF NOT EXISTS bronze_api_responses (
	response_id VARCHAR(36) NOT NULL, 
	run_id VARCHAR(36) NOT NULL, 
	endpoint VARCHAR(48) NOT NULL, 
	discovery_method VARCHAR(24) NOT NULL, 
	discovery_query VARCHAR(64) NOT NULL, 
	region_code VARCHAR(8), 
	category_id INTEGER, 
	page_index INTEGER NOT NULL, 
	request_params TEXT NOT NULL, 
	http_status INTEGER NOT NULL, 
	item_count INTEGER NOT NULL, 
	payload_gz BYTEA NOT NULL, 
	payload_sha256 VARCHAR(64) NOT NULL, 
	fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (response_id)
);
CREATE INDEX IF NOT EXISTS ix_bronze_fetched ON bronze_api_responses (fetched_at);
CREATE INDEX IF NOT EXISTS ix_bronze_run ON bronze_api_responses (run_id);

CREATE TABLE IF NOT EXISTS dim_channels (
	channel_id VARCHAR(64) NOT NULL, 
	channel_title TEXT, 
	first_observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (channel_id)
);

CREATE TABLE IF NOT EXISTS dim_regions (
	region_code VARCHAR(8) NOT NULL, 
	country_name VARCHAR(100) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	first_ingested_at TIMESTAMP WITH TIME ZONE, 
	last_ingested_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (region_code)
);

CREATE TABLE IF NOT EXISTS dim_topics (
	topic_id VARCHAR(64) NOT NULL, 
	canonical_name VARCHAR(200) NOT NULL, 
	canonical_key VARCHAR(200) NOT NULL, 
	topic_kind VARCHAR(16) NOT NULL, 
	category VARCHAR(64) NOT NULL, 
	parent_topic_id VARCHAR(64), 
	keywords TEXT, 
	first_observed_at TIMESTAMP WITH TIME ZONE, 
	last_observed_at TIMESTAMP WITH TIME ZONE, 
	created_run_id VARCHAR(36), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (topic_id)
);
CREATE INDEX IF NOT EXISTS ix_dim_topics_kind ON dim_topics (topic_kind);

CREATE TABLE IF NOT EXISTS dim_videos (
	video_id VARCHAR(32) NOT NULL, 
	title TEXT NOT NULL, 
	channel_id VARCHAR(64) NOT NULL, 
	category_id INTEGER, 
	category_name VARCHAR(64), 
	published_at TIMESTAMP WITH TIME ZONE, 
	duration_seconds INTEGER, 
	tags TEXT, 
	description_snippet TEXT, 
	thumbnail_url TEXT, 
	default_language VARCHAR(16), 
	first_observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	latest_view_count BIGINT, 
	latest_like_count BIGINT, 
	latest_comment_count BIGINT, 
	PRIMARY KEY (video_id)
);
CREATE INDEX IF NOT EXISTS ix_dim_videos_channel ON dim_videos (channel_id);
CREATE INDEX IF NOT EXISTS ix_dim_videos_last_obs ON dim_videos (last_observed_at);

CREATE TABLE IF NOT EXISTS discovery_state (
	key VARCHAR(64) NOT NULL, 
	value TEXT NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (key)
);

CREATE TABLE IF NOT EXISTS dq_results (
	id SERIAL NOT NULL, 
	run_id VARCHAR(36) NOT NULL, 
	check_name VARCHAR(64) NOT NULL, 
	severity VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	total_checked INTEGER NOT NULL, 
	passed INTEGER NOT NULL, 
	failed INTEGER NOT NULL, 
	warnings INTEGER NOT NULL, 
	details TEXT, 
	executed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_dq_run_check UNIQUE (run_id, check_name)
);
CREATE INDEX IF NOT EXISTS ix_dq_executed ON dq_results (executed_at);

CREATE TABLE IF NOT EXISTS fact_topic_observations (
	run_id VARCHAR(36) NOT NULL, 
	observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	video_count INTEGER NOT NULL, 
	channel_count INTEGER NOT NULL, 
	total_views BIGINT, 
	avg_views FLOAT, 
	total_likes BIGINT, 
	total_comments BIGINT, 
	avg_engagement_rate FLOAT, 
	views_gained BIGINT, 
	views_per_hour FLOAT, 
	popularity_score FLOAT NOT NULL, 
	popularity_rank INTEGER NOT NULL, 
	CONSTRAINT pk_fact_topic_obs PRIMARY KEY (run_id, topic_id, region_code)
);
CREATE INDEX IF NOT EXISTS ix_fto_observed ON fact_topic_observations (observed_at);
CREATE INDEX IF NOT EXISTS ix_fto_region_time ON fact_topic_observations (region_code, observed_at);
CREATE INDEX IF NOT EXISTS ix_fto_topic_region_time ON fact_topic_observations (topic_id, region_code, observed_at);

CREATE TABLE IF NOT EXISTS fact_video_observations (
	run_id VARCHAR(36) NOT NULL, 
	observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	video_id VARCHAR(32) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	discovery_method VARCHAR(24) NOT NULL, 
	discovery_query VARCHAR(64) NOT NULL, 
	chart_category_id INTEGER, 
	chart_rank INTEGER, 
	view_count BIGINT, 
	like_count BIGINT, 
	comment_count BIGINT, 
	engagement_rate FLOAT, 
	views_delta BIGINT, 
	hours_since_prev FLOAT, 
	views_per_hour FLOAT, 
	CONSTRAINT pk_fact_video_obs PRIMARY KEY (run_id, video_id, region_code, discovery_method, discovery_query)
);
CREATE INDEX IF NOT EXISTS ix_fvo_observed ON fact_video_observations (observed_at);
CREATE INDEX IF NOT EXISTS ix_fvo_region_time ON fact_video_observations (region_code, observed_at);
CREATE INDEX IF NOT EXISTS ix_fvo_video_time ON fact_video_observations (video_id, observed_at);

CREATE TABLE IF NOT EXISTS gold_category_summary (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	category VARCHAR(64) NOT NULL, 
	video_count INTEGER NOT NULL, 
	topic_count INTEGER NOT NULL, 
	total_views BIGINT, 
	avg_engagement_rate FLOAT, 
	CONSTRAINT pk_gold_category PRIMARY KEY (region_code, category)
);

CREATE TABLE IF NOT EXISTS gold_channel_performance (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	channel_id VARCHAR(64) NOT NULL, 
	channel_title TEXT, 
	region_code VARCHAR(8) NOT NULL, 
	appearances_24h INTEGER NOT NULL, 
	videos_24h INTEGER NOT NULL, 
	total_views BIGINT, 
	avg_engagement_rate FLOAT, 
	views_per_hour FLOAT, 
	top_topic_id VARCHAR(64), 
	top_topic_name VARCHAR(200), 
	topics_count INTEGER, 
	regions_count INTEGER, 
	latest_observed_at TIMESTAMP WITH TIME ZONE, 
	CONSTRAINT pk_gold_channel PRIMARY KEY (channel_id, region_code)
);

CREATE TABLE IF NOT EXISTS gold_publications (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	snapshot_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	published_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	data_source VARCHAR(32) NOT NULL, 
	row_counts TEXT, 
	PRIMARY KEY (snapshot_run_id)
);
CREATE INDEX IF NOT EXISTS ix_gold_pub_at ON gold_publications (published_at);

CREATE TABLE IF NOT EXISTS gold_regional_comparison (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	popularity_score FLOAT NOT NULL, 
	popularity_rank INTEGER NOT NULL, 
	regions_present INTEGER NOT NULL, 
	is_shared BOOLEAN NOT NULL, 
	is_country_specific BOOLEAN NOT NULL, 
	CONSTRAINT pk_gold_regional PRIMARY KEY (topic_id, region_code)
);

CREATE TABLE IF NOT EXISTS gold_topic_growth (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	snapshot_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	"window" VARCHAR(8) NOT NULL, 
	window_minutes INTEGER NOT NULL, 
	compare_run_id VARCHAR(36), 
	compare_observed_at TIMESTAMP WITH TIME ZONE, 
	score_now FLOAT, 
	score_prev FLOAT, 
	score_growth_pct FLOAT, 
	video_count_now INTEGER, 
	video_count_prev INTEGER, 
	video_count_growth_pct FLOAT, 
	vph_now FLOAT, 
	vph_prev FLOAT, 
	vph_growth_pct FLOAT, 
	velocity FLOAT, 
	acceleration FLOAT, 
	prior_growth_pct FLOAT, 
	growth_status VARCHAR(24) NOT NULL, 
	CONSTRAINT pk_gold_growth PRIMARY KEY (region_code, topic_id, "window")
);

CREATE TABLE IF NOT EXISTS gold_trending_topics (
	snapshot_run_id VARCHAR(36) NOT NULL, 
	snapshot_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	topic_name VARCHAR(200) NOT NULL, 
	category VARCHAR(64) NOT NULL, 
	topic_kind VARCHAR(16) NOT NULL, 
	popularity_rank INTEGER NOT NULL, 
	rank_change_1h INTEGER, 
	rank_change_24h INTEGER, 
	popularity_score FLOAT NOT NULL, 
	video_count INTEGER NOT NULL, 
	channel_count INTEGER NOT NULL, 
	total_views BIGINT, 
	views_per_hour FLOAT, 
	avg_engagement_rate FLOAT, 
	growth_24h_pct FLOAT, 
	lifecycle_stage VARCHAR(16) NOT NULL, 
	first_observed_at TIMESTAMP WITH TIME ZONE, 
	last_observed_at TIMESTAMP WITH TIME ZONE, 
	consecutive_observations INTEGER NOT NULL, 
	CONSTRAINT pk_gold_trending PRIMARY KEY (region_code, topic_id)
);

CREATE TABLE IF NOT EXISTS pipeline_lock (
	lock_name VARCHAR(64) NOT NULL, 
	owner_run_id VARCHAR(36) NOT NULL, 
	acquired_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (lock_name)
);

CREATE TABLE IF NOT EXISTS pipeline_runs (
	run_id VARCHAR(36) NOT NULL, 
	trigger VARCHAR(32) NOT NULL, 
	data_source VARCHAR(32) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	duration_seconds FLOAT, 
	records_bronze INTEGER, 
	records_silver INTEGER, 
	records_quarantined INTEGER, 
	records_gold INTEGER, 
	videos_observed INTEGER, 
	topics_observed INTEGER, 
	quota_used INTEGER, 
	gold_published BOOLEAN NOT NULL, 
	dq_status VARCHAR(16), 
	error_message TEXT, 
	git_sha VARCHAR(64), 
	stage_summary TEXT, 
	PRIMARY KEY (run_id)
);
CREATE INDEX IF NOT EXISTS ix_pipeline_runs_started ON pipeline_runs (started_at);
CREATE INDEX IF NOT EXISTS ix_pipeline_runs_status ON pipeline_runs (status, started_at);

CREATE TABLE IF NOT EXISTS pipeline_stage_runs (
	id SERIAL NOT NULL, 
	run_id VARCHAR(36) NOT NULL, 
	stage VARCHAR(48) NOT NULL, 
	stage_order INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	duration_ms INTEGER, 
	records_in INTEGER, 
	records_out INTEGER, 
	attempts INTEGER, 
	error TEXT, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_stage_run UNIQUE (run_id, stage)
);
CREATE INDEX IF NOT EXISTS ix_stage_runs_run ON pipeline_stage_runs (run_id);

CREATE TABLE IF NOT EXISTS quarantine_records (
	id SERIAL NOT NULL, 
	run_id VARCHAR(36) NOT NULL, 
	stage VARCHAR(32) NOT NULL, 
	check_name VARCHAR(64) NOT NULL, 
	record_key VARCHAR(200), 
	reason TEXT NOT NULL, 
	payload TEXT, 
	quarantined_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS ix_quarantine_at ON quarantine_records (quarantined_at);
CREATE INDEX IF NOT EXISTS ix_quarantine_run ON quarantine_records (run_id);

CREATE TABLE IF NOT EXISTS schema_migrations (
	version SERIAL NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	applied_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (version)
);

CREATE TABLE IF NOT EXISTS silver_video_observations (
	run_id VARCHAR(36) NOT NULL, 
	video_id VARCHAR(32) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	discovery_method VARCHAR(24) NOT NULL, 
	discovery_query VARCHAR(64) NOT NULL, 
	chart_category_id INTEGER, 
	chart_rank INTEGER, 
	observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	channel_id VARCHAR(64) NOT NULL, 
	category_id INTEGER, 
	published_at TIMESTAMP WITH TIME ZONE, 
	duration_seconds INTEGER, 
	view_count BIGINT, 
	like_count BIGINT, 
	comment_count BIGINT, 
	metadata_hash VARCHAR(16), 
	CONSTRAINT pk_silver_obs PRIMARY KEY (run_id, video_id, region_code, discovery_method, discovery_query)
);
CREATE INDEX IF NOT EXISTS ix_silver_observed ON silver_video_observations (observed_at);

CREATE TABLE IF NOT EXISTS topic_aliases (
	alias_key VARCHAR(200) NOT NULL, 
	topic_id VARCHAR(64) NOT NULL, 
	surface_form TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (alias_key)
);
CREATE INDEX IF NOT EXISTS ix_alias_topic ON topic_aliases (topic_id);

CREATE TABLE IF NOT EXISTS tracked_videos (
	video_id VARCHAR(32) NOT NULL, 
	region_code VARCHAR(8) NOT NULL, 
	discovery_query VARCHAR(64) NOT NULL, 
	first_discovered_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_discovered_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	track_until TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_tracked_videos PRIMARY KEY (video_id, region_code, discovery_query)
);
CREATE INDEX IF NOT EXISTS ix_tracked_until ON tracked_videos (track_until);

INSERT INTO schema_migrations (version, description, applied_at) VALUES (1, 'initial medallion schema (bronze/silver/gold + operational metadata)', now()) ON CONFLICT (version) DO NOTHING;
